record.field:
# Esta acción está pensada para cancelar movimientos pendientes tanto en recepciones en 1 paso como mas de uno.
# Para recepciones un paso el albarán será supplier -> internal y se cancelará todo lo que no esté validado.
# Para mas de un paso el albarán que entrará al filtro será el primero supplier -> transit y se cancelará todo lo que no esté validado. Esto no cancela otros parciales de un movimientos que hayan
# podido validarse ya pero que tengan un destino pendiente. Sí cancela todos los destinos del movimiento que se cancela.

for line in records:
  for move in line.move_ids:
    if move.location_id.usage == "supplier" and (move.location_dest_id.usage == 'transit' or move.location_dest_id.usage == 'internal') and move.state not in ['done', 'cancel']:
      move._action_cancel()
